$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path (Split-Path $PSScriptRoot);$delivery=Join-Path $root 'Livraison'
function Info($file,$kind){$im=[System.Drawing.Image]::FromFile($file.FullName);$w=$im.Width;$h=$im.Height;$im.Dispose();[pscustomobject]@{File=[System.IO.Path]::GetRelativePath($root,$file.FullName);Kind=$kind;Width=$w;Height=$h;Bytes=$file.Length;SHA256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash}}
$files=@(Get-ChildItem -LiteralPath (Join-Path $root 'Exports_4K\V07') -File -Filter '*.png'|Sort-Object Name)
$masters=@(Get-ChildItem -LiteralPath (Join-Path $root 'Masters\V07') -File -Filter '*_master.png'|Sort-Object Name)
if($files.Count -ne 8 -or $masters.Count -ne 8){throw 'Eight exports and eight masters required'}
$manifest=@($files|ForEach-Object {Info $_ 'Final composite with enlarged components'})
$masterManifest=@($masters|ForEach-Object {Info $_ 'Master without final grain'})
if(@(($manifest+$masterManifest)|Where-Object {$_.Width -ne 3840 -or $_.Height -ne 2160}).Count){throw 'Incorrect dimensions'}
$manifest|Export-Csv -NoTypeInformation -Encoding utf8 (Join-Path $PSScriptRoot 'Exports_V07_manifest.csv')
$masterManifest|Export-Csv -NoTypeInformation -Encoding utf8 (Join-Path $PSScriptRoot 'Masters_V07_manifest.csv')
$sourceFiles=@(Get-ChildItem -LiteralPath (Join-Path $root 'Sources_HD') -Recurse -File -Filter '*.jpg')
if($sourceFiles.Count -ne 54){throw 'Expected 54 original stills'}
$sourceChecks=foreach($person in @('Casper','Riz','Tableau')){foreach($row in (Import-Csv -LiteralPath (Join-Path (Split-Path $PSScriptRoot) ($person+'_manifest.csv')))){$file=Join-Path $root ('Sources_HD\'+$person+'\'+$row.File);$hash=(Get-FileHash -LiteralPath $file).Hash;if($hash -ne $row.SHA256){throw ('Source changed: '+$row.File)};[pscustomobject]@{File=$row.File;OriginalSHA256Unchanged=$true}}}
$sourceChecks|Export-Csv -NoTypeInformation -Encoding utf8 (Join-Path $PSScriptRoot 'Original_sources_verified.csv')
foreach($ref in (Import-Csv -LiteralPath (Join-Path $PSScriptRoot 'References_manifest.csv'))){$file=Join-Path $root ('References\Charts_V07\'+$ref.File);if((Get-FileHash -LiteralPath $file).Hash -ne $ref.SHA256){throw 'Style reference changed'}}
function CreateZip($path,$members,$flat=$false){if(Test-Path -LiteralPath $path){throw ('Archive exists: '+$path)};$archive=[System.IO.Compression.ZipFile]::Open($path,[System.IO.Compression.ZipArchiveMode]::Create);try{foreach($file in $members){$entry=if($flat){$file.Name}else{[System.IO.Path]::GetRelativePath($root,$file.FullName).Replace('\','/')};$null=[System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($archive,$file.FullName,$entry,[System.IO.Compression.CompressionLevel]::Optimal)}}finally{$archive.Dispose()}}
function VerifyZip($path,$expected,$flat=$false){$a=[System.IO.Compression.ZipFile]::OpenRead($path);try{if($a.Entries.Count -ne $expected.Count){throw 'ZIP count mismatch'};foreach($entry in $a.Entries){$disk=if($flat){$expected|Where-Object {$_.Name -eq $entry.Name}|Select-Object -First 1}else{Get-Item -LiteralPath (Join-Path $root $entry.FullName)};$stream=$entry.Open();$sha=[System.Security.Cryptography.SHA256]::Create();try{$hash=[Convert]::ToHexString($sha.ComputeHash($stream))}finally{$stream.Dispose();$sha.Dispose()};if($hash -ne (Get-FileHash -LiteralPath $disk.FullName).Hash){throw ('Archive hash mismatch: '+$entry.FullName)}};return $a.Entries.Count}finally{$a.Dispose()}}
$zip=Join-Path $delivery 'Casper_8_Thumbnails_V07_3840x2160.zip';CreateZip $zip $files $true;$zipCount=VerifyZip $zip $files $true
$report=[ordered]@{Version='V07';Date='2026-10-13';PNGCount=8;MasterCount=8;Width=3840;Height=2160;Native4K=$false;OriginalSourceCount=54;OriginalSourceHashesUnchanged=$true;UserStyleReferences=6;ReferencesPreserved=$true;NewImageGenCalls=0;VideoOrProxyDownloaded=$false;FinalGrain='5 percent uniform monochromatic, single final pass';VisualReview='Eight previews at 320 and 640; 01, 02, 06 and 08 at 1280; native enlarged portrait and screen crops reviewed';NewScreens=@('01','02');PortraitScale06='460 / 420 = +9.52 percent';GlowChanges='All eight, directional feathered light; 08 significantly reduced';LocalPixelComparison='Corrections_locales_V06_V07.csv';ChangesOutsideRequestedAreas=0;UnchangedPhotographicComponents=12;UnchangedFaceSampleRegions=10;ExternalTextAndTypographyGeometryUnchanged=$true;Archive=[System.IO.Path]::GetFileName($zip);ArchiveEntries=$zipCount;ArchivePayloadHashesMatch=$true;ArchiveBytes=(Get-Item -LiteralPath $zip).Length;ArchiveSHA256=(Get-FileHash -LiteralPath $zip).Hash}
$report|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $PSScriptRoot 'Verification_V07.json') -Encoding utf8
$members=[System.Collections.Generic.List[System.IO.FileInfo]]::new()
foreach($folder in @('Sources_HD','Selections','References','Masters\V07','Exports_4K\V07','Apercus\V07','Suivi\V07','Suivi\V06','Suivi\V05','Suivi\V04','Suivi\V03','Suivi\Fonts')){foreach($f in (Get-ChildItem -LiteralPath (Join-Path $root $folder) -Recurse -File)){$members.Add($f)}}
foreach($path in @('LISEZ_MOI_V07.txt','LISEZ_MOI_V06.txt','LISEZ_MOI_V05.txt','LISEZ_MOI_V04.txt','LISEZ_MOI_V03.txt','Suivi\Transcript_Frameio_lu.txt','Suivi\Notes_editoriales.txt','Suivi\Sources_HD_manifest_complet.csv','Suivi\Casper_manifest.csv','Suivi\Riz_manifest.csv','Suivi\Tableau_manifest.csv')){$members.Add((Get-Item -LiteralPath (Join-Path $root $path)))}
$production=Join-Path $delivery 'Casper_Production_V07.zip';CreateZip $production $members;$count=VerifyZip $production $members
$prod=[ordered]@{File=[System.IO.Path]::GetFileName($production);Files=$count;AllPayloadHashesMatch=$true;Bytes=(Get-Item -LiteralPath $production).Length;SHA256=(Get-FileHash -LiteralPath $production).Hash}
$prod|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $delivery 'Verification_Production_V07.json') -Encoding utf8
$report|ConvertTo-Json -Compress;$prod|ConvertTo-Json -Compress
